# name: trial_index_yes_slope
# description: OLS slope of yes (0/1) on trial_index (per 100 trials); observed > model means people drift toward saying "yes" more as the session goes on, which the trial-invariant model cannot produce, observed < model means a drift toward "no".
def test_statistic(df):
    x = df["trial_index"].to_numpy(dtype=float) / 100.0
    y = df["rating"].to_numpy(dtype=float)
    xc = x - x.mean()
    v = (xc ** 2).sum()
    if v == 0:
        return 0.0
    return float((xc * (y - y.mean())).sum() / v)

# name: four_example_set_mean_sd
# description: Standard deviation, across four-example sets, of each set's overall yes-rate; observed > model means sets differ in how readily people say "yes" more than the model predicts (model too homogeneous across set types), observed < model means less heterogeneity than predicted.
def test_statistic(df):
    n = df["number_set"].astype(str).str.count(",") + 1
    sub = df[n == 4]
    if len(sub) == 0:
        return 0.0
    g = sub.groupby("number_set")["rating"].mean()
    return float(g.std(ddof=0))

# name: target_is_example_yes_rate
# description: Yes-rate on trials whose target is one of the shown examples; observed < model means people reject already-shown examples far more often than a concept-membership model (which puts them in nearly every posterior concept) predicts, observed > model means the reverse.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
    t = df["target"].astype(float).to_numpy()[:, None]
    m = (ex == t).any(axis=1)
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].to_numpy(dtype=float)[m].mean())

# name: single_example_within_set_spread
# description: Mean over single-example sets of the standard deviation (across targets) of per-(set,target) yes-rates; observed > model means people discriminate between targets after one example more sharply than the model's evidence-scarce guessing allows (guessing too flat), observed < model means responses are flatter than predicted.
def test_statistic(df):
    s = df["number_set"].astype(str)
    sub = df[~s.str.contains(",")]
    if len(sub) == 0:
        return 0.0
    cell = sub.groupby(["number_set", "target"])["rating"].mean().reset_index()
    sd = cell.groupby("number_set")["rating"].std(ddof=0)
    sd = sd[cell.groupby("number_set").size() >= 3]
    if len(sd) == 0:
        return 0.0
    return float(sd.mean())
